const ACCENT_BG: Record<string, string> = {
  "chart-1": "bg-chart-1/10 text-chart-1 ring-chart-1/20",
  "chart-2": "bg-chart-2/10 text-chart-2 ring-chart-2/20",
  "chart-3": "bg-chart-3/10 text-chart-3 ring-chart-3/20",
};

